/** @param {NS} ns */
export async function main(ns) {
  const rootedServers = new Set();
  const portOpeners = [];

  // Check for port openers
  if (ns.fileExists('BruteSSH.exe')) portOpeners.push(() => ns.brutessh);
  if (ns.fileExists('FTPCrack.exe')) portOpeners.push(() => ns.ftpcrack);
  if (ns.fileExists('relaySMTP.exe')) portOpeners.push(() => ns.relaysmtp);
  if (ns.fileExists('HTTPWorm.exe')) portOpeners.push(() => ns.httpworm);
  if (ns.fileExists('SQLInject.exe')) portOpeners.push(() => ns.sqlinject);

  let target = 'n00dles';
  const queue = ['home'];
  const visited = new Set(['home']);

  // BFS to discover all servers
  while (queue.length > 0) {
    const srv = queue.shift();
    const neighbors = ns.scan(srv);
    for (const next of neighbors) {
      if (!visited.has(next)) {
        visited.add(next);
        queue.push(next);
      }
    }
  }

  // Attempt root on all servers
  for (const srv of visited) {
    if (ns.hasRootAccess(srv)) {
      rootedServers.add(srv);
    } else {
      const ports = ns.getServerNumPortsRequired(srv);
      for (let i = 0; i < Math.min(ports, portOpeners.length); i++) {
        portOpeners[i]()(srv);
      }
      if (ports <= portOpeners.length) {
        ns.nuke(srv);
        rootedServers.add(srv);
      }
    }
  }

  let hackCount = 0, weakenCount = 0, growCount = 0;
  const minHackLevel = ns.getHackingLevel();

  while (true) {
    // Find best rooted target
    let best = null, bestMoney = 0;
    for (const srv of rootedServers) {
      const reqLevel = ns.getServerRequiredHackingLevel(srv);
      if (reqLevel <= minHackLevel) {
        const money = ns.getServerMoneyAvailable(srv);
        if (money > bestMoney) {
          bestMoney = money;
          best = srv;
        }
      }
    }

    if (!best) {
      target = 'n00dles';
      best = 'n00dles';
    } else {
      target = best;
    }

    // Weaken/grow/hack loop
    const sec = ns.getServerSecurityLevel(target);
    const minSec = ns.getServerMinSecurityLevel(target);
    const money = ns.getServerMoneyAvailable(target);
    const maxMoney = ns.getServerMaxMoney(target);

    if (sec > minSec + 5) {
      await ns.weaken(target);
      weakenCount++;
    } else if (money < maxMoney * 0.75) {
      await ns.grow(target);
      growCount++;
    } else {
      await ns.hack(target);
      hackCount++;
    }

    if ((hackCount + weakenCount + growCount) % 10 === 0) {
      ns.print(`[${target}] hack=${hackCount} weaken=${weakenCount} grow=${growCount}`);
    }
  }
}

